import'package:flutter/material.dart';import'../services/mobile_sensors.dart';import'../services/funzi_api.dart';import'science_3d_viewport.dart';
class NativeLabToolsPage extends StatefulWidget{const NativeLabToolsPage({super.key});@override State<NativeLabToolsPage>createState()=>_NativeLabToolsPageState();}
class _NativeLabToolsPageState extends State<NativeLabToolsPage>{MobileSensorAdapter?adapter;String status='Disconnected';List<SensorReading>samples=[];final notebook=TextEditingController();Future<void>connect(String kind)async{try{adapter=kind=='BLE'?BleSensorAdapter():UsbSerialSensorAdapter();await adapter!.connect();setState(()=>status='${adapter!.id} connected');}catch(e){setState(()=>status='Connection error: $e');}}Future<void>read()async{try{final r=await adapter!.read();setState(()=>samples=r);}catch(e){setState(()=>status='Read error: $e');}}Future<void>upload()async{if(notebook.text.isEmpty||adapter==null||samples.isEmpty)return;await FunziApi.ingestSensorSamples(notebook.text,adapter!.id,samples.map((x)=>x.toJson()).toList());setState(()=>status='${samples.length} samples accepted by trusted backend');}@override void dispose(){adapter?.disconnect();notebook.dispose();super.dispose();}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[Text('Native Lab Tools',style:Theme.of(c).textTheme.headlineMedium),const Text('Interactive 3D'),const Science3DViewport(),const Divider(),Text('Physical sensors',style:Theme.of(c).textTheme.titleLarge),Text(status),Wrap(spacing:8,children:[FilledButton(onPressed:()=>connect('BLE'),child:const Text('Connect BLE')),OutlinedButton(onPressed:()=>connect('USB'),child:const Text('Connect USB')),OutlinedButton(onPressed:adapter==null?null:read,child:const Text('Read sample'))]),...samples.map((x)=>ListTile(title:Text(x.quantity),subtitle:Text(x.sensorId),trailing:Text('${x.value} ${x.unit}'))),TextField(controller:notebook,decoration:const InputDecoration(labelText:'Notebook ID for trusted ingestion')),FilledButton(onPressed:samples.isEmpty?null:upload,child:const Text('Attach samples to notebook'))]);}}